// 本文件由 scripts/gen-pstack-skills.mjs 从 packages/pstack/skills/*/SKILL.md 生成。
// 不要手改：改技能请改 skills/ 下的原文，然后重跑 `pnpm --filter @void/pstack run gen`。
// `scripts/pack-all.ps1` 会用 --check 校验它与磁盘一致。

/** vendored 技能在目录里的元数据；正文由运行期从 SKILL.md 现读。 */
export interface PstackSkillEntry {
  /** kebab-case 技能名，与 skills/ 下的目录名一致。 */
  readonly name: string
  /** 面向发现消费者的路由描述；宿主按 500 字符上限渲染它。 */
  readonly description: string
  /** 是否出现在面向模型的目录与 loader 里。 */
  readonly modelInvocable: boolean
  /** 是否出现在面向用户的 `/` 菜单里。 */
  readonly userInvocable: boolean
}

/** 全部 vendored 技能，按名称排序。 */
export const PSTACK_SKILLS: readonly PstackSkillEntry[] = [
  { name: "architect", description: "先定类型、签名与模块结构，再让实现填空，全程在环内把关。 Sketch types, signatures, and module structure before code, then stay in the loop while implementation fills in. Use for /architect, 'architect this', 'design this', or non-trivial work where jumping to code would lock in the wrong shape.", modelInvocable: false, userInvocable: true },
  { name: "arena", description: "并行生成 N 个候选方案做同一件事，选一个当基底，再把落选者最强的部分嫁接进来。 Spawn N parallel candidates at the same task, pick a base, graft the strongest parts of the losers into it. Use for /arena, 'arena this', 'throw it in the arena', or when one attempt at a non-trivial artifact would lock in the wrong shape.", modelInvocable: false, userInvocable: true },
  { name: "automate-me", description: "把用户的偏好和工作方式起草或修订成个人 -mode 技能，可选用最近对话记录作证据。 Use for \"automate me\", \"create/update/refresh my -mode skill\", \"turn/capture my preferences or working style into a skill\", or wanting agents to follow how the user works. Drafts or revises a personal -mode skill via create-skill + unslop, optionally pulling fresh evidence from recent transcripts.", modelInvocable: false, userInvocable: true },
  { name: "benchmark-checklist", description: "在汇报或采信一项性能测量前逐项体检：限速、调优、上限、误差、可复现性、相关性，以及活是否真的干过。 Vet a perf measurement (limiter, tuning, limits, errors, repeatability, relevance, and whether the work happened) before you report or act on it. Use when you run a benchmark or report a speedup or regression you measured.", modelInvocable: false, userInvocable: true },
  { name: "blast-radius", description: "在变更上线前找出它可能在别处弄坏什么（不止于 diff），并跑真代码证明它安全所依赖的那一个事实。 Find what a change could break somewhere else before it ships, beyond the diff, and prove the one fact it's safe because of by running real code instead of writing it up. Use for 'blast radius of X', 'what could this break', or reviewing a small diff you don't trust.", modelInvocable: false, userInvocable: true },
  { name: "bro", description: "用不带术语的人话把上一条消息复述一遍。 Restate the last message in plain human language, with no jargon.", modelInvocable: false, userInvocable: true },
  { name: "correct", description: "找出 agent 在本仓库反复犯的错误并让每一个都变得不可能再犯：先用架构，再是类型、报错即点明修法的 lint、测试，文档放最后；每个检查都要能证明它在真实历史错误上失败。 Find the mistakes agents keep repeating in this repo and make each one impossible. Try architecture first, then types, then a lint whose error names the fix, then a test, and write docs last. Prove each check fails on a real past mistake. Repeat this each time the operator corrects you. Use for /correct.", modelInvocable: false, userInvocable: true },
  { name: "create-formal-verification-skill", description: "生成项目本地的形式化验证技能，对「bug 代价最高、测试覆盖最少」的代码用最合适的验证工具做验证，不限语言。 Generate a project-local skill that formally verifies the code where a bug costs the most and tests reach the least, in any language, with whichever verification tool fits. Use for /create-formal-verification-skill, \"model-check this race\", \"prove this invariant\", or when concurrency, retries, state machines, parsers, or unsafe code need more than tests.", modelInvocable: false, userInvocable: true },
  { name: "create-verification-skill", description: "生成项目本地的验证技能，像用户那样驱动你的应用，不限语言、框架或平台。 Generate a project-local verification skill that drives your app the way a user does — any language, framework, or platform. Use for /create-verification-skill, \"make a control skill for this repo\", or when a project has no scripted way to prove UI/CLI/service behavior.", modelInvocable: false, userInvocable: true },
  { name: "figure-it-out", description: "没有更窄的剧本可用时，设计一套可审计的行动剧本：大型迁移、多段的大改动，或人离开一阵回来再审阅的工作；按任务配比严谨度，跑假设循环并记录决策。 Design an auditable playbook when no narrower one fits - a large migration, an ambitious multi-part change, or work a human reviews after stepping away. Scales rigor to the task, runs a hypothesis loop, and logs decisions. Use for /figure-it-out or 'figure it out'.", modelInvocable: false, userInvocable: true },
  { name: "how", description: "解释子系统架构、运行时流程与上手心智模型，也回答放置、归属、分层这类问题。 Use for \"how does X work\", code walkthroughs before changing something, and placement / ownership / layering questions (\"where should this live\", \"which package owns this\", \"is this the right layer\"). Explains subsystem architecture, runtime flow, onboarding mental models. Use why for motivation.", modelInvocable: false, userInvocable: true },
  { name: "in-your-own-words", description: "用自己的话复述你理解到的用户目标，以及对方想解决的问题。 Restate in your own words what you think the user's goals are and what problem they're trying to solve. Use for /in-your-own-words.", modelInvocable: false, userInvocable: true },
  { name: "interrogate", description: "从多个独立角度对改动做对抗性评审，召集多个 LLM 评审员各自挑刺、找盲点。 Use for \"interrogate\", \"adversarial review\", \"multi-model review\", \"challenge this\", \"stress test this code\", \"find blind spots\", or \"tear this apart\". Multiple LLM reviewers challenge changes from independent angles.", modelInvocable: false, userInvocable: true },
  { name: "ketchup", description: "用大白话配小幅图示，把用户上次发言以来这段对话里发生的变化补给他，并逐条列出在等他处理的事项。 Catch the user up on what changed in this chat since their last message, in plain words and small visuals. List every item waiting on them with what they need to decide it from the reply alone. Use for /ketchup.", modelInvocable: false, userInvocable: true },
  { name: "maintain-verification-skill", description: "定期巡检，让项目的验证技能与功能地图保持诚实：每个功能并行读源码，再用一个真实会话跑遍全部功能，最多提交一个已证修正的 PR。 Periodic pass that keeps a project's verification skill and feature map honest - parallel source readers per feature, one live session driving every feature, at most one PR of proven corrections. Use for /maintain-verification-skill or \"audit the verify skill\".", modelInvocable: false, userInvocable: true },
  { name: "make-bot-ui", description: "做一个能通过 webhook 唤醒 Grok Bot 的自定义界面（页面、看板、按钮），也用于用户需要提供 webhook sender key，或需要把该界面暴露到 Tailscale 时。 Use when building a custom UI (page, dashboard, buttons) that should wake a Grok Bot over a webhook, when the user must provide a webhook sender key, or when exposing that UI on Tailscale.", modelInvocable: false, userInvocable: true },
  { name: "no-comments", description: "召唤 Comment Sicko，修掉被采纳的意见，并为已声明的约束给出编码落地方式。 Spawn Comment Sicko, fix accepted findings, and offer encodings for claimed constraints.", modelInvocable: false, userInvocable: true },
  { name: "poteto-help", description: "引导用户完成 pstack 配置、使用 /poteto-mode，并为具体任务挑选合适的技能、剧本或原则。 Guides users through pstack setup, /poteto-mode, and picking the skill, playbook, or principle for a task. Type /poteto-help with a question.", modelInvocable: false, userInvocable: true },
  { name: "poteto-mode", description: "poteto 的 agent 风格：回答简洁而细节充足、审慎派子代理、文字不注水、代码简单、工作经过验证。 poteto's agent style for concise, detailed responses, deliberate subagents, unslopped prose, simple code, and verified work. Use for poteto, /poteto-mode, or requests to work in this style.", modelInvocable: false, userInvocable: true },
  { name: "principle-attack-the-premise", description: "两个及以上共享同一前提的修复在同一道关卡失败时，先把前提写下来直接验证，再写下一个假设它成立的修复。 Apply when two or more fixes that share one premise have failed the same gate. Write the premise down and test it directly before you write another fix that assumes it.", modelInvocable: false, userInvocable: true },
  { name: "principle-boundary-discipline", description: "接校验、错误处理或框架适配器时，把守卫集中在系统边界（CLI、配置、网络、外部 API），信任内部类型，业务逻辑留在纯函数里。 Apply when wiring validation, error handling, or framework adapters. Concentrate guards at system boundaries (CLI, config, network, external APIs); trust internal types and keep business logic in pure functions.", modelInvocable: false, userInvocable: true },
  { name: "principle-build-the-lever", description: "任何非琐碎的工作（不只是批量活）都造一个能完成或能证明它的工具：codemod、脚本、生成器，或子代理照做的技能；这个工具就是评审者可重跑的产物。 Apply to any non-trivial work, not just bulk work - edits, migrations, analyses, checks. Build the tool that does it or proves it (codemod, script, generator, or a skill your subagents follow) instead of working by hand. The tool is the artifact a reviewer can rerun.", modelInvocable: false, userInvocable: true },
  { name: "principle-encode-lessons-in-structure", description: "同一句指令写第二遍、或发现某个纠正在反复出现时，把规则编码成 lint、元数据标记、运行时检查或脚本，而不是再写一段文字。 Apply when you catch yourself writing the same instruction a second time, or notice a recurring correction. Encode the rule as a lint, metadata flag, runtime check, or script instead of more text.", modelInvocable: false, userInvocable: true },
  { name: "principle-exhaust-the-design-space", description: "面对代码库里没有先例的全新 UI 交互或架构决策时，先做 2-3 个互相竞争的原型并排比较，再定方案。 Apply when facing a novel UI interaction or architectural decision with no precedent in the codebase. Build 2-3 competing prototypes and compare side by side before committing.", modelInvocable: false, userInvocable: true },
  { name: "principle-experience-first", description: "遇到产品、UX 或功能范围取舍时，宁要用户爽感不要实现省事；宁可少而精，不要多而糙。 Apply when product, UX, or feature-scope tradeoffs come up. Choose user delight over implementation convenience; ship fewer polished features over more rough ones.", modelInvocable: false, userInvocable: true },
  { name: "principle-explain-the-number", description: "采信、汇报或依据自己测出的数字行动前，先弄清是什么在限制它，并排除它测的不是你以为的那件事：加速比、回退、吞吐、延迟或评测结果。 Apply before you trust, report, or act on a number you measured - a speedup, a regression, a throughput, a latency, or an eval result. Find what limits it, and rule out that it measured something other than the work you think.", modelInvocable: false, userInvocable: true },
  { name: "principle-fix-root-causes", description: "调试时把每个症状追到系统第一次出错的地方并在那里修；只有它处理的状态本身合法，加守卫才算修复。 Apply when debugging. Trace each symptom back to the first place the system went wrong and fix it there. A guard is a fix only when the state it handles is legitimate.", modelInvocable: false, userInvocable: true },
  { name: "principle-foundational-thinking", description: "写逻辑前先定核心类型与数据结构、排好脚手架与功能的先后、想清楚并发参与者共享什么；数据结构对了，下游代码自然清楚。 Apply before writing logic - choosing core types and data structures, sequencing scaffold-vs-feature work, asking what concurrent actors share. Get the data structures right so downstream code becomes obvious.", modelInvocable: false, userInvocable: true },
  { name: "principle-guard-the-context-window", description: "上下文窗口快被占满时适用——大输出、长文件、重复读取、fan-out 规划。把批量内容交给 subagents，主线程只留摘要，不塞原始载荷。Apply when context is filling up - large outputs, long files, repeated reads, fan-out planning. Route bulk to subagents; keep summaries in the main thread, not raw payloads.", modelInvocable: false, userInvocable: true },
  { name: "principle-laziness-protocol", description: "重构、评估 diff 规模，或想加抽象、加层、穿透传信号时适用。偏向删除，用能解决问题的最小改动。Apply when refactoring, evaluating diff size, or tempted to add abstractions, layers, or signal threading. Bias toward deletion and the smallest change that solves the problem.", modelInvocable: false, userInvocable: true },
  { name: "principle-make-operations-idempotent", description: "设计命令、生命周期步骤或处理循环时适用——这些流程要扛住崩溃、重启与重试。无论此前是否只跑了一半，都收敛到同一个终态。Apply when designing commands, lifecycle steps, or processing loops that run amid crashes, restarts, and retries. Converge to the same end state regardless of partial prior runs.", modelInvocable: false, userInvocable: true },
  { name: "principle-migrate-callers-then-delete-legacy-apis", description: "引入新的内部 API、而旧调用方还在时适用。同一波里迁移调用方并删掉旧 API，不要留兼容层。Apply when introducing a new internal API while old callers still exist. Migrate callers and delete the old API in the same wave instead of preserving compatibility layers.", modelInvocable: false, userInvocable: true },
  { name: "principle-minimize-reader-load", description: "审阅或改造难以追踪的代码时适用。数一数从问题到答案之间隔了几层、读者脑子里要装多少隐藏状态；合并只有单一调用方的包装层，缩小可变作用域。Apply when reviewing or shaping code that's hard to trace. Count layers between question and answer, and hidden state in the reader's head; collapse one-caller wrappers and shrink mutable scope.", modelInvocable: false, userInvocable: true },
  { name: "principle-model-the-domain", description: "写有状态的逻辑时适用，或代码分支很多、同一种形状假设在多个文件里重复时适用。Apply when writing stateful logic, or when code branches a lot or repeats a shape assumption across files.", modelInvocable: false, userInvocable: true },
  { name: "principle-never-block-on-the-human", description: "面对可逆的工作，想开口问「should I do X?」时适用。Apply when tempted to ask 'should I do X?' on reversible work.", modelInvocable: false, userInvocable: true },
  { name: "principle-outcome-oriented-execution", description: "分阶段边界的计划性重写与迁移期间适用。向目标架构收敛，别用一次性的兼容代码去维持平滑的中间态。Apply during planned rewrites and migrations with explicit phase boundaries. Converge on the target architecture; don't preserve smooth intermediate states with throwaway compatibility code.", modelInvocable: false, userInvocable: true },
  { name: "principle-prove-it-works", description: "任务做完、宣布完成之前适用。对着真实产物验证（跑一遍功能、读真实取值、看 diff），而不是代理指标、自述或「能编译」。Apply after completing a task, before declaring done. Verify against the real artifact (run the feature, read the actual value, inspect the diff), not a proxy, self-report, or 'it compiles.'", modelInvocable: false, userInvocable: true },
  { name: "principle-redesign-from-first-principles", description: "要把新需求塞进已有设计时适用。回到第一性原理重做设计，而不是在旧结构上打补丁。Apply when integrating a new requirement into an existing design.", modelInvocable: false, userInvocable: true },
  { name: "principle-separate-before-serializing-shared-state", description: "并发参与者可能写同一个文件、分支、key 或状态对象时适用。先消除共享；只有当「唯一共享写者」确实是必须维持的不变量时，才用结构化的串行化。Apply when concurrent actors might write to the same file, branch, key, or state object. Eliminate the sharing first; serialize structurally only when one shared writer is a real invariant.", modelInvocable: false, userInvocable: true },
  { name: "principle-sequence-verifiable-units", description: "多步骤工作（清扫、迁移、一批同类修改）以及如何堆叠 commit 和 PR 时适用。把工作拆成一个个小单元，每个都以可验证的状态收尾；逐个检查再往下走，并安排好交付顺序，让这个序列本身就向 reviewer 证明自己。Apply to multi-step work (sweeps, migrations, runs of similar edits) and to how you stack commits and PRs. Break work into small units that each end in a verifiable state, check each before the next, and order delivery so the sequence proves itself to a reviewer.", modelInvocable: false, userInvocable: true },
  { name: "principle-subtract-before-you-add", description: "安排一次新增、重构或重写的顺序时适用。先删掉死代码、冗余校验和桩引用，再在更简单的地基上动工。Apply when sequencing an addition, refactor, or rewrite. Remove dead code, redundant validators, and stub references first, then build on the simpler base.", modelInvocable: false, userInvocable: true },
  { name: "principle-test-behavior-not-implementation", description: "写测试、改测试或保留一个测试时适用。断言代码使用者能观察到的行为，这样行为一坏测试就红，而只改内部实现时测试仍然绿。Apply when you write, change, or keep a test. Assert what the code's users can observe, so that the test fails when that behavior breaks and keeps passing when only the internals change.", modelInvocable: false, userInvocable: true },
  { name: "principle-type-system-discipline", description: "设计类型、审阅函数签名，或用任何静态类型语言写代码时适用。让非法状态无法表示，给语义原语打上 brand，在边界解析外部数据，穷尽所有变体，从权威 schema 派生。Apply when designing types, reviewing a function signature, or writing code in any statically-typed language. Make illegal states unrepresentable, brand semantic primitives, parse external data at boundaries, exhaust variants, derive from authoritative schemas.", modelInvocable: false, userInvocable: true },
  { name: "recall", description: "从自己的聊天记录、实时状态和共享记录（用户反馈、既往修复、事故）里重建最近的工作上下文，再交回一份紧凑的当前状态简报。Use for 'recall my work on X', 'catch me up', 'what have I been working on', 'where did I leave off', before starting or resuming work.", modelInvocable: false, userInvocable: true },
  { name: "reflect", description: "对当前对话记录并行派出三个 review subagents，提炼经验教训，并把每条都落到对某个现有技能的具体修改上。Use when the user says reflect.", modelInvocable: false, userInvocable: true },
  { name: "setup-pstack", description: "配置 pstack 每个角色用哪个模型、给多少推理预算。它会探测你可用哪些模型，并写一条始终生效的规则来覆盖技能默认值。Use for /setup-pstack, \"configure pstack models\", \"pstack budget\", or changing pstack's model choices.", modelInvocable: true, userInvocable: true },
  { name: "sharpen", description: "动手前先把任务磨锋利：专家会怎么做、用户真正想要什么、以及该细化到什么程度。Use for /sharpen.", modelInvocable: false, userInvocable: true },
  { name: "show-me-your-work", description: "为长跑或无人值守的工作留一份可复核的决策轨迹——一个 TSV 日志，每个决策一行（做了什么、为什么、证据、结果）。默认只放本地；当 reviewer 需要靠这份轨迹才能相信结果时再提交。Use for /show-me-your-work, autonomous or multi-phase runs, or work a human reviews after stepping away.", modelInvocable: false, userInvocable: true },
  { name: "swarm", description: "铺开 N 个并行 worker，把它们的结果收干，再返回一份报告。Use for /swarm, 'swarm this', or parallel coverage, races, gauntlets, and exploration.", modelInvocable: false, userInvocable: true },
  { name: "tdd", description: "测试驱动开发：先写一个失败的测试，再让它通过。只在用户明确要求 TDD、要求一个失败测试或回归测试时使用，或当这个 bug 有明显且便宜的本地测试目标时使用。测试路径不清楚、代价高、集成过重或未被要求时跳过。Use only when the user explicitly asks for TDD, a failing test, or a regression test, OR when the bug has an obvious cheap local test target. Skip when the test path is unclear, expensive, integration-heavy, or not requested.", modelInvocable: false, userInvocable: true },
  { name: "teach", description: "把一摊工作讲清楚，让人真的听懂。它会跑 `how` 和 `why` 两个技能，把各自的发现编织成一份清晰的解释。Use for 'teach me this', 'help me really understand X', 'explain this change or subsystem to me'.", modelInvocable: false, userInvocable: true },
  { name: "technical-writing", description: "分层技术写作标准，涵盖 Diátaxis 结构、Google developer style 句式、STE 指令规则与 Global English 语法。Use for /technical-writing or when writing or reviewing docs, RFCs, readmes, PR descriptions, or commit messages.", modelInvocable: false, userInvocable: true },
  { name: "typescript-best-practices", description: "TypeScript 最佳实践。读或改任何 .ts 或 .tsx 文件时使用。Use when reading or editing any .ts or .tsx file.", modelInvocable: false, userInvocable: true },
  { name: "unslop", description: "从任何写作里删掉 AI 味的痕迹（AI tells）。Cut AI tells from any writing.", modelInvocable: false, userInvocable: true },
  { name: "why", description: "回答「为什么」：设计理由、回归、复盘与数据阈值。发现可用 MCP，并行查各类证据后返回带引用的权衡解读。Use for 'why does X work this way', 'why we picked Y', design rationale, regressions, postmortems, or data-backed thresholds. Discovers available MCPs and queries each evidence category (source control, issue tracker, long-form docs, real-time chat, infrastructure observability, error tracking, product analytics warehouse) in parallel, then returns a cited read on decisions and tradeoffs. Use how for runtime behavior.", modelInvocable: false, userInvocable: true },
]

/** 技能数量。测试用它盯住「vendor 目录被换版本」这类静默变化。 */
export const PSTACK_SKILL_COUNT = 55
